<template>
  <div class="campaigns-page">
    <div class="page-head">
      <div><div class="eyebrow">投放管理 / Meta</div><h2>广告系列</h2><p>统一查看、同步和控制 Campaign、AdSet 与 Ad。</p></div>
      <div><el-button :loading="loading" @click="refresh">刷新</el-button><el-button v-if="canCampaignAction('SYNC')" type="primary" @click="sync">同步 Meta</el-button></div>
    </div>
    <el-alert v-if="taskNotice" :title="taskNotice" :type="taskNoticeType" :closable="true" show-icon style="margin-bottom: 12px" @close="taskNotice = ''" />
    <el-tabs v-model="activeTab" @tab-change="onTabChange">
      <el-tab-pane label="广告系列" name="campaigns">
        <el-card shadow="never">
          <div class="filters"><el-input v-model="keywordFilter" placeholder="搜索广告系列名称或 Meta ID" clearable @keyup.enter="loadCampaigns(1)" /><el-input v-model="accountFilter" placeholder="广告账户 ID" clearable @keyup.enter="loadCampaigns(1)" /><el-select v-model="statusFilter" placeholder="系统状态" clearable @change="loadCampaigns(1)"><el-option label="启用" value="ACTIVE" /><el-option label="暂停" value="PAUSED" /><el-option label="已归档" value="ARCHIVED" /><el-option label="已删除 / 历史本地移除" value="DELETED" /></el-select><el-button @click="loadCampaigns(1)">筛选</el-button></div>
          <div class="batch-toolbar"><span>已选 {{ selectedCampaigns.length }} 个广告系列</span><el-button v-if="canCampaignAction('SYNC')" size="small" :disabled="!selectedCampaigns.length" @click="syncSelected('CAMPAIGN', selectedCampaigns)">批量同步</el-button><el-button v-if="canCampaignAction('PAUSE')" size="small" :disabled="!selectedCampaigns.length" @click="batchAction('PAUSE', 'CAMPAIGN', selectedCampaigns)">批量暂停</el-button><el-button v-if="canCampaignAction('ENABLE')" size="small" :disabled="!selectedCampaigns.length" @click="batchAction('ENABLE', 'CAMPAIGN', selectedCampaigns)">批量启用</el-button><el-button v-if="canCampaignAction('ARCHIVE')" size="small" type="warning" :disabled="!selectedCampaigns.length" @click="batchAction('ARCHIVE', 'CAMPAIGN', selectedCampaigns)">批量本地归档</el-button><el-button v-if="canCampaignAction('DELETE')" size="small" type="danger" :disabled="!selectedCampaigns.length" @click="batchAction('DELETE', 'CAMPAIGN', selectedCampaigns)">批量删除 Meta 广告</el-button><el-button v-if="canCampaignAction('RESTORE')" size="small" type="success" :disabled="!selectedCampaigns.length" @click="batchAction('RESTORE', 'CAMPAIGN', selectedCampaigns)">批量取消归档</el-button></div>
          <el-table :data="campaigns" v-loading="loading" @selection-change="selectedCampaigns = $event"><el-table-column type="selection" width="46" /><el-table-column prop="name" label="广告系列" /><el-table-column label="广告账户" show-overflow-tooltip><template #default="{ row }">{{ row.grouped ? `${row.account_count} 个账户：${row.account_name}` : row.account_name }}</template></el-table-column><el-table-column label="Meta ID" show-overflow-tooltip><template #default="{ row }">{{ row.grouped ? `${row.account_count} 个账户` : row.meta_campaign_id }}</template></el-table-column><el-table-column prop="objective" label="目标" /><el-table-column label="Meta 状态"><template #default="{ row }"><el-tag size="small" :type="row.meta_status === 'ACTIVE' ? 'success' : 'warning'">{{ row.grouped ? '按账户查看' : row.meta_status || '未同步' }}</el-tag></template></el-table-column><el-table-column label="系统状态"><template #default="{ row }"><el-tag size="small" :type="row.status === 'ACTIVE' ? 'success' : 'info'">{{ row.grouped ? '已合并展示' : row.deletion_state === 'LOCAL_REMOVED' ? '历史本地移除' : row.status }}</el-tag></template></el-table-column><el-table-column label="操作进度" width="120"><template #default="{ row }">{{ objectOperationLabel(row as DeliveryRow) }}</template></el-table-column><el-table-column prop="last_synced_at" label="最近同步" width="170" :formatter="formatDateTimeCell" /><el-table-column label="操作" width="430"><template #default="{ row }"><el-button link type="primary" @click="showDetail(row as TableRow<typeof campaigns>, 'CAMPAIGN')">详情</el-button><el-button v-if="canCampaignAction('SYNC')" link type="primary" @click="syncSelected('CAMPAIGN', [row as TableRow<typeof campaigns>])">同步</el-button><el-button link type="primary" @click="openAdsets(row as TableRow<typeof campaigns>)">广告组</el-button><el-button v-if="(['ACTIVE','PAUSED'].includes(row.status) || row.grouped) && (canCampaignAction('PAUSE') || canCampaignAction('ENABLE'))" link type="warning" @click="changeStatus(row as TableRow<typeof campaigns>, 'CAMPAIGN')">{{ row.grouped ? '批量启停' : row.status === 'ACTIVE' ? '暂停' : '启用' }}</el-button><el-button v-if="(['ACTIVE','PAUSED'].includes(row.status) || row.grouped) && canCampaignAction('ARCHIVE')" link type="danger" @click="archive(row as TableRow<typeof campaigns>, 'CAMPAIGN')">本地归档</el-button><el-button v-if="row.deletion_state !== 'REMOTE_DELETED' && canCampaignAction('DELETE')" link type="danger" @click="removePublished(row as TableRow<typeof campaigns>, 'CAMPAIGN')">删除 Meta 广告</el-button><el-button v-if="row.status === 'ARCHIVED' && canCampaignAction('RESTORE')" link type="success" @click="restore(row as TableRow<typeof campaigns>, 'CAMPAIGN')">取消归档</el-button><el-button v-if="row.deletion_state === 'REMOTE_DELETED' && (userStore.isAdmin || userStore.hasPermission('job:create'))" link type="primary" @click="copyDeletedCampaign(row as TableRow<typeof campaigns>)">复制新建</el-button></template></el-table-column></el-table>
          <div class="pagination-bar"><el-pagination v-model:current-page="campaignPage" v-model:page-size="campaignPageSize" :total="campaignTotal" :page-sizes="[10, 20, 50]" layout="total, sizes, prev, pager, next" background @current-change="loadCampaigns" @size-change="handleCampaignPageSizeChange" /></div>
          <el-empty v-if="!loading && !campaigns.length" description="暂无广告系列，请先完成批量投放" />
        </el-card>
      </el-tab-pane>
      <el-tab-pane label="广告组" name="adsets">
        <el-card shadow="never">
          <div class="sub-head"><div class="selector-row"><el-select v-model="selectedCampaignId" placeholder="选择广告系列" filterable clearable @change="selectCampaign"><el-option v-for="item in campaigns" :key="item.id" :label="`${item.name} · ${item.account_name || item.meta_campaign_id}`" :value="item.id" /></el-select><el-select v-model="adsetStatusFilter" placeholder="状态" clearable @change="selectedCampaignId && loadAdsets(selectedCampaignId, 1)"><el-option label="启用" value="ACTIVE" /><el-option label="暂停" value="PAUSED" /><el-option label="归档" value="ARCHIVED" /><el-option label="已删除 / 历史本地移除" value="DELETED" /></el-select></div><el-button link @click="activeTab = 'campaigns'">返回广告系列</el-button></div>
          <div class="batch-toolbar"><span>已选 {{ selectedAdsets.length }} 个广告组</span><el-button v-if="canCampaignAction('SYNC')" size="small" :disabled="!selectedAdsets.length" @click="syncSelected('ADSET', selectedAdsets)">批量同步</el-button><el-button v-if="canCampaignAction('PAUSE')" size="small" :disabled="!selectedAdsets.length" @click="batchAction('PAUSE', 'ADSET', selectedAdsets)">批量暂停</el-button><el-button v-if="canCampaignAction('ENABLE')" size="small" :disabled="!selectedAdsets.length" @click="batchAction('ENABLE', 'ADSET', selectedAdsets)">批量启用</el-button><el-button v-if="canCampaignAction('ARCHIVE')" size="small" type="warning" :disabled="!selectedAdsets.length" @click="batchAction('ARCHIVE', 'ADSET', selectedAdsets)">批量本地归档</el-button><el-button v-if="canCampaignAction('DELETE')" size="small" type="danger" :disabled="!selectedAdsets.length" @click="batchAction('DELETE', 'ADSET', selectedAdsets)">批量删除 Meta 广告</el-button><el-button v-if="canCampaignAction('RESTORE')" size="small" type="success" :disabled="!selectedAdsets.length" @click="batchAction('RESTORE', 'ADSET', selectedAdsets)">批量取消归档</el-button></div>
          <el-table :data="adsets" v-loading="subLoading" @selection-change="selectedAdsets = $event"><el-table-column type="selection" width="46" /><el-table-column prop="name" label="广告组" /><el-table-column prop="meta_adset_id" label="Meta ID" /><el-table-column prop="optimization_goal" label="优化目标" /><el-table-column prop="daily_budget" label="日预算" /><el-table-column label="状态"><template #default="{ row }"><el-tag size="small" :type="row.status === 'ACTIVE' ? 'success' : 'info'">{{ row.deletion_state === 'LOCAL_REMOVED' ? '历史本地移除' : row.status || '未知' }}</el-tag></template></el-table-column><el-table-column label="操作进度" width="120"><template #default="{ row }">{{ objectOperationLabel(row as DeliveryRow) }}</template></el-table-column><el-table-column prop="last_synced_at" label="最近同步" width="170" :formatter="formatDateTimeCell" /><el-table-column label="操作" width="460"><template #default="{ row }"><el-button link type="primary" @click="showDetail(row as TableRow<typeof adsets>, 'ADSET')">详情</el-button><el-button v-if="canCampaignAction('SYNC')" link type="primary" @click="syncSelected('ADSET', [row as TableRow<typeof adsets>])">同步</el-button><el-button link type="primary" @click="openAds(row as TableRow<typeof adsets>)">查看广告</el-button><el-button v-if="['ACTIVE','PAUSED'].includes(row.status) && (canCampaignAction('PAUSE') || canCampaignAction('ENABLE'))" link type="warning" @click="changeStatus(row as TableRow<typeof adsets>, 'ADSET')">{{ row.status === 'ACTIVE' ? '暂停' : '启用' }}</el-button><el-button v-if="['ACTIVE','PAUSED'].includes(row.status) && canCampaignAction('ARCHIVE')" link type="danger" @click="archive(row as TableRow<typeof adsets>, 'ADSET')">本地归档</el-button><el-button v-if="row.deletion_state !== 'REMOTE_DELETED' && canCampaignAction('DELETE')" link type="danger" @click="removePublished(row as TableRow<typeof adsets>, 'ADSET')">删除 Meta 广告</el-button><el-button v-if="row.status === 'ARCHIVED' && canCampaignAction('RESTORE')" link type="success" @click="restore(row as TableRow<typeof adsets>, 'ADSET')">取消归档</el-button></template></el-table-column></el-table>
          <div class="pagination-bar"><el-pagination v-model:current-page="adsetPage" v-model:page-size="adsetPageSize" :total="adsetTotal" :page-sizes="[10, 20, 50]" layout="total, sizes, prev, pager, next" background @current-change="loadSelectedAdsets" @size-change="handleAdsetPageSizeChange" /></div>
          <el-empty v-if="!subLoading && selectedCampaignId && !adsets.length" description="该广告系列暂无广告组" />
        </el-card>
      </el-tab-pane>
      <el-tab-pane label="广告" name="ads">
        <el-card shadow="never">
          <div class="sub-head"><div class="selector-row"><el-select v-model="selectedAdsetId" placeholder="选择广告组" filterable clearable @change="selectAdset"><el-option v-for="item in adsets" :key="item.id" :label="`${item.name} · ${item.meta_adset_id}`" :value="item.id" /></el-select><el-select v-model="adStatusFilter" placeholder="状态" clearable @change="selectedAdsetId && loadAds(selectedAdsetId, 1)"><el-option label="启用" value="ACTIVE" /><el-option label="暂停" value="PAUSED" /><el-option label="归档" value="ARCHIVED" /><el-option label="已删除 / 历史本地移除" value="DELETED" /></el-select></div><el-button link @click="activeTab = 'adsets'">返回广告组</el-button></div>
          <div class="batch-toolbar"><span>已选 {{ selectedAds.length }} 个广告</span><el-button v-if="canCampaignAction('SYNC')" size="small" :disabled="!selectedAds.length" @click="syncSelected('AD', selectedAds)">批量同步</el-button><el-button v-if="canCampaignAction('PAUSE')" size="small" :disabled="!selectedAds.length" @click="batchAction('PAUSE', 'AD', selectedAds)">批量暂停</el-button><el-button v-if="canCampaignAction('ENABLE')" size="small" :disabled="!selectedAds.length" @click="batchAction('ENABLE', 'AD', selectedAds)">批量启用</el-button><el-button v-if="canCampaignAction('ARCHIVE')" size="small" type="warning" :disabled="!selectedAds.length" @click="batchAction('ARCHIVE', 'AD', selectedAds)">批量本地归档</el-button><el-button v-if="canCampaignAction('DELETE')" size="small" type="danger" :disabled="!selectedAds.length" @click="batchAction('DELETE', 'AD', selectedAds)">批量删除 Meta 广告</el-button><el-button v-if="canCampaignAction('RESTORE')" size="small" type="success" :disabled="!selectedAds.length" @click="batchAction('RESTORE', 'AD', selectedAds)">批量取消归档</el-button></div>
          <el-table :data="ads" v-loading="subLoading" @selection-change="selectedAds = $event"><el-table-column type="selection" width="46" /><el-table-column prop="name" label="广告" /><el-table-column prop="meta_ad_id" label="Meta ID" /><el-table-column prop="meta_status" label="Meta 状态" /><el-table-column label="系统状态"><template #default="{ row }">{{ row.deletion_state === 'LOCAL_REMOVED' ? '历史本地移除' : row.status }}</template></el-table-column><el-table-column label="操作进度" width="120"><template #default="{ row }">{{ objectOperationLabel(row as DeliveryRow) }}</template></el-table-column><el-table-column prop="last_synced_at" label="最近同步" width="170" :formatter="formatDateTimeCell" /><el-table-column label="操作" width="450"><template #default="{ row }"><el-button link type="primary" @click="showDetail(row as TableRow<typeof ads>, 'AD')">详情</el-button><el-button v-if="canCampaignAction('SYNC')" link type="primary" @click="syncSelected('AD', [row as TableRow<typeof ads>])">同步</el-button><el-button v-if="['ACTIVE','PAUSED'].includes(row.status) && (canCampaignAction('PAUSE') || canCampaignAction('ENABLE'))" link type="warning" @click="changeStatus(row as TableRow<typeof ads>, 'AD')">{{ row.status === 'ACTIVE' ? '暂停' : '启用' }}</el-button><el-button v-if="['ACTIVE','PAUSED'].includes(row.status) && canCampaignAction('ARCHIVE')" link type="danger" @click="archive(row as TableRow<typeof ads>, 'AD')">本地归档</el-button><el-button v-if="row.deletion_state !== 'REMOTE_DELETED' && canCampaignAction('DELETE')" link type="danger" @click="removePublished(row as TableRow<typeof ads>, 'AD')">删除 Meta 广告</el-button><el-button v-if="row.status === 'ARCHIVED' && canCampaignAction('RESTORE')" link type="success" @click="restore(row as TableRow<typeof ads>, 'AD')">取消归档</el-button></template></el-table-column></el-table>
          <div class="pagination-bar"><el-pagination v-model:current-page="adPage" v-model:page-size="adPageSize" :total="adTotal" :page-sizes="[10, 20, 50]" layout="total, sizes, prev, pager, next" background @current-change="loadSelectedAds" @size-change="handleAdPageSizeChange" /></div>
          <el-empty v-if="!subLoading && selectedAdsetId && !ads.length" description="该广告组暂无广告" />
        </el-card>
      </el-tab-pane>
      <el-tab-pane label="异步任务" name="jobs">
        <el-card shadow="never">
          <el-alert v-if="batchResult" :type="batchResult.failed ? 'warning' : 'info'" show-icon closable @close="batchResult = null"><template #title>{{ batchResult.title }}</template><div class="result-summary">提交 {{ batchResult.count }} 个对象；{{ batchResult.message }} <el-button link type="primary" @click="loadJobs">刷新结果</el-button></div></el-alert>
          <div class="sub-head">投放任务结果</div><el-table :data="jobs" v-loading="jobLoading"><el-table-column prop="id" label="投放任务 ID" show-overflow-tooltip /><el-table-column prop="action_type" label="动作" /><el-table-column prop="status" label="状态" /><el-table-column label="结果"><template #default="{ row }"><span class="success-text">{{ row.success_count }}</span> / <span class="failed-text">{{ row.failed_count }}</span> / {{ row.total_accounts }}</template></el-table-column><el-table-column prop="created_at" label="创建时间" :formatter="formatDateTimeCell" /><el-table-column label="操作" width="90"><template #default="{ row }"><el-button link type="primary" @click="openJob(row as TableRow<typeof jobs>)">查看结果</el-button></template></el-table-column></el-table>
          <el-divider /><div class="sub-head">Meta 同步任务</div><el-table :data="metaTasks" size="small"><el-table-column prop="task_id" label="Celery Task ID" show-overflow-tooltip /><el-table-column prop="task_type" label="类型" /><el-table-column prop="object_type" label="对象" /><el-table-column prop="status" label="状态" /><el-table-column prop="result_summary" label="结果" show-overflow-tooltip /><el-table-column prop="created_at" label="提交时间" :formatter="formatDateTimeCell" /></el-table>
          <el-divider /><div class="sub-head">媒体操作与本地归档记录</div><el-table :data="deliveryActions" size="small"><el-table-column label="动作" width="120"><template #default="{ row }">{{ actionLabel(row.action) }}</template></el-table-column><el-table-column prop="object_type" label="对象类型" width="110" /><el-table-column prop="object_name" label="对象名称" show-overflow-tooltip /><el-table-column prop="account_name" label="广告账户" show-overflow-tooltip /><el-table-column prop="meta_object_id" label="Meta ID" show-overflow-tooltip /><el-table-column prop="object_id" label="本地 ID" show-overflow-tooltip /><el-table-column label="状态" width="130"><template #default="{ row }">{{ actionStateLabel(row as DeliveryAction) }}</template></el-table-column><el-table-column prop="desired_status" label="目标状态" width="110" /><el-table-column prop="remote_status" label="Meta 状态" width="110" /><el-table-column prop="error_message" label="失败原因" show-overflow-tooltip /><el-table-column prop="created_at" label="提交时间" :formatter="formatDateTimeCell" /><el-table-column prop="finished_at" label="结果时间" :formatter="formatDateTimeCell" /><el-table-column label="操作" width="180"><template #default="{ row }"><el-button v-if="['FAILED','UNKNOWN'].includes(row.status) && canCampaignAction(row.action)" link type="warning" @click="retryAction(row as TableRow<typeof deliveryActions>)">{{ row.status === 'UNKNOWN' ? '核对结果' : '重试失败项' }}</el-button><el-button link type="primary" @click="showActionDetail(row as TableRow<typeof deliveryActions>)">详情</el-button></template></el-table-column></el-table>
          <el-empty v-if="!jobLoading && !jobs.length && !metaTasks.length && !deliveryActions.length" description="暂无异步任务" />
        </el-card>
      </el-tab-pane>
    </el-tabs>
    <el-dialog v-model="detailVisible" title="投放对象详情" width="820px"><div v-if="detail" class="detail-content"><el-descriptions :column="2" border><el-descriptions-item label="对象类型">{{ typeLabel(detail.object_type) }}</el-descriptions-item><el-descriptions-item label="对象名称">{{ detail.object?.name || '-' }}</el-descriptions-item><el-descriptions-item label="本地 ID">{{ detail.object?.id || '-' }}</el-descriptions-item><el-descriptions-item label="Meta ID">{{ metaObjectId(detail) }}</el-descriptions-item><el-descriptions-item label="系统状态"><el-tag>{{ detail.object?.deletion_state === 'LOCAL_REMOVED' ? '历史本地移除（尚未确认 Meta 删除）' : detail.object?.status || '-' }}</el-tag></el-descriptions-item><el-descriptions-item label="Meta 状态"><el-tag :type="(detail.object?.meta_status) === 'ACTIVE' ? 'success' : 'warning'">{{ detail.object?.meta_status || '未同步' }}</el-tag></el-descriptions-item><el-descriptions-item label="目标状态">{{ detail.object?.desired_status || '-' }}</el-descriptions-item><el-descriptions-item label="最近同步">{{ displayDateTime(detail.object?.last_synced_at, '未同步') }}</el-descriptions-item><el-descriptions-item label="广告账户" :span="2">{{ detail.account?.account_name || detail.account?.account_id || '-' }}</el-descriptions-item><el-descriptions-item v-if="detail.object?.last_error" label="同步异常" :span="2"><span class="failed-text">{{ detail.object?.last_error }}</span></el-descriptions-item></el-descriptions><div v-if="detail.ancestors?.campaign || detail.ancestors?.adset" class="detail-section"><h4>所属层级</h4>{{ detail.ancestors.campaign?.name || '' }}<span v-if="detail.ancestors.adset"> / {{ detail.ancestors.adset.name }}</span></div><div v-if="detail.children?.length" class="detail-section"><h4>下级对象</h4><el-table :data="detail.children" size="small"><el-table-column prop="name" label="名称" /><el-table-column prop="meta_adset_id" label="Meta AdSet ID" /><el-table-column prop="meta_ad_id" label="Meta Ad ID" /><el-table-column prop="status" label="状态" /><el-table-column prop="meta_status" label="Meta 状态" /><el-table-column v-if="detail.object_type === 'CAMPAIGN'" label="广告数"><template #default="{ row }">{{ row.ads?.length || 0 }}</template></el-table-column></el-table></div><div class="detail-section"><h4>最近操作结果</h4><el-table :data="detail.recent_actions || []" size="small"><el-table-column prop="action" label="动作" /><el-table-column prop="status" label="状态" /><el-table-column prop="remote_status" label="Meta 状态" /><el-table-column prop="error_message" label="失败原因" show-overflow-tooltip /><el-table-column prop="created_at" label="时间" :formatter="formatDateTimeCell" /></el-table><el-empty v-if="!detail.recent_actions?.length" description="暂无对象操作记录" /></div><div v-if="detail.legacy?.job_item?.response_payload?.cleanup_attempted" class="detail-section"><el-alert :type="detail.legacy.job_item.response_payload.cleanup_failed ? 'error' : 'success'" :title="detail.legacy.job_item.response_payload.cleanup_failed ? '发布失败，部分 Meta 对象未清理' : '发布失败，Meta 对象已自动回滚'" show-icon /></div><div v-if="detail.legacy?.creative_config" class="detail-section"><h4>创意与落地页</h4><pre class="detail-json">{{ JSON.stringify(detail.legacy.creative_config?.creative_format === 'CAROUSEL' ? detail.legacy.creative_config?.carousel_cards || [] : detail.legacy.creative_config?.creatives || [], null, 2) }}</pre></div></div></el-dialog>
    <el-dialog v-model="deleteVisible" :title="`删除 Meta ${typeLabel(deleteType)}`" width="900px" :close-on-click-modal="false">
      <el-alert type="warning" :closable="false" show-icon title="此操作会删除 Meta 侧对象，删除后无法恢复。删除上级会影响全部下级投放；下方数量为本地已同步记录，本地历史数据保留。" />
      <p>请确认具体账户实例，已选 {{ deleteSelection.length }} 个{{ typeLabel(deleteType) }}，涉及 {{ new Set(deleteSelection.map(item => item.accountId)).size }} 个账户。</p>
      <el-table ref="deleteTable" :data="deleteTargets" row-key="id" @selection-change="deleteSelection = $event">
        <el-table-column type="selection" width="46" /><el-table-column prop="name" label="名称" /><el-table-column prop="accountName" label="广告账户" /><el-table-column prop="metaId" label="Meta ID" /><el-table-column prop="scope" label="下级影响范围" /><el-table-column prop="state" label="当前状态" />
      </el-table>
      <template #footer><el-button :disabled="deleteSubmitting" @click="deleteVisible = false">取消</el-button><el-button type="danger" :disabled="!deleteSelection.length" :loading="deleteSubmitting" @click="submitMetaDeletion">确认删除 Meta 对象</el-button></template>
    </el-dialog>
    <el-dialog v-model="jobDetailVisible" title="批量操作结果" width="820px"><div v-if="jobDetail"><el-descriptions :column="4" border><el-descriptions-item label="动作">{{ jobDetail.action_type }}</el-descriptions-item><el-descriptions-item label="状态">{{ jobDetail.status }}</el-descriptions-item><el-descriptions-item label="成功">{{ jobDetail.success_count }}</el-descriptions-item><el-descriptions-item label="失败">{{ jobDetail.failed_count }}</el-descriptions-item></el-descriptions><el-table :data="jobDetail.items || []" size="small" style="margin-top: 16px"><el-table-column prop="ad_account_id" label="广告账户" /><el-table-column prop="status" label="结果" /><el-table-column prop="error_code" label="错误码" /><el-table-column prop="error_message" label="失败原因" show-overflow-tooltip /><el-table-column prop="updated_at" label="完成时间" :formatter="formatDateTimeCell" /></el-table></div></el-dialog>
  </div>
</template>
<script setup lang="ts">
import { formatDateTimeCell, formatDateTime as displayDateTime } from '@/utils/dateTime'
import { nextTick, onBeforeUnmount, onMounted, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { useRouter } from 'vue-router'
import { templatesApi } from '@/api/templates'
import { accountApi } from '@/api/admin'
import { campaignsApi, type DeliveryAction, type DeliveryObjectDetail, type MetaAd, type MetaAdSet, type MetaCampaign } from '@/api/campaigns'
import { jobsApi, type CampaignJob } from '@/api/jobs'
import { useUserStore } from '@/stores/userStore'
type DeliveryRow = MetaCampaign | MetaAdSet | MetaAd
type ObjectType = 'CAMPAIGN' | 'ADSET' | 'AD'
const userStore = useUserStore()
const router = useRouter()
const activeTab = ref('campaigns'); const loading = ref(false); const subLoading = ref(false); const jobLoading = ref(false)
const campaigns = ref<MetaCampaign[]>([]); const adsets = ref<MetaAdSet[]>([]); const ads = ref<MetaAd[]>([]); const jobs = ref<CampaignJob[]>([]); const metaTasks = ref<any[]>([]); const deliveryActions = ref<DeliveryAction[]>([])
const selectedCampaign = ref<MetaCampaign | null>(null); const selectedAdset = ref<MetaAdSet | null>(null); const selectedCampaigns = ref<MetaCampaign[]>([]); const selectedAdsets = ref<MetaAdSet[]>([]); const selectedAds = ref<MetaAd[]>([])
const selectedCampaignId = ref(''); const selectedAdsetId = ref(''); const adsetStatusFilter = ref(''); const adStatusFilter = ref('')
const campaignPage = ref(1); const campaignPageSize = ref(20); const campaignTotal = ref(0)
const adsetPage = ref(1); const adsetPageSize = ref(20); const adsetTotal = ref(0)
const adPage = ref(1); const adPageSize = ref(20); const adTotal = ref(0)
const detailVisible = ref(false); const detail = ref<DeliveryObjectDetail & { legacy?: any } | null>(null); const jobDetailVisible = ref(false); const jobDetail = ref<any>(null)
const accountFilter = ref(''); const statusFilter = ref(''); const keywordFilter = ref(''); const taskNotice = ref(''); const taskNoticeType = ref<'info' | 'success' | 'warning' | 'error'>('info')
type DeleteTarget = { id: string; name: string; accountId: string; accountName: string; metaId: string; scope: string; state: string }
const deleteVisible = ref(false); const deleteType = ref<ObjectType>('CAMPAIGN'); const deleteTargets = ref<DeleteTarget[]>([]); const deleteSelection = ref<DeleteTarget[]>([]); const deleteSubmitting = ref(false)
const deleteTable = ref<{ toggleRowSelection: (row: DeleteTarget, selected: boolean) => void }>()
const batchResult = ref<{ title: string; count: number; message: string; failed?: boolean } | null>(null)
let actionTimer: ReturnType<typeof setTimeout> | undefined; let refreshTimer: ReturnType<typeof setTimeout> | undefined; let taskTimer: ReturnType<typeof setTimeout> | undefined; let jobTimer: ReturnType<typeof setTimeout> | undefined
const campaignPermissions: Record<string, string> = { PAUSE: 'campaign:pause', ENABLE: 'campaign:enable', ARCHIVE: 'campaign:archive', DELETE: 'campaign:delete', RESTORE: 'campaign:restore', SYNC: 'campaign:sync', UPDATE_BUDGET: 'campaign:update_budget' }
function canCampaignAction(action: string) { return userStore.isAdmin || userStore.hasPermission(campaignPermissions[action] || '') || (['PAUSE', 'ENABLE'].includes(action) && userStore.hasPermission('job:create')) }
async function loadCampaigns(page = campaignPage.value) { loading.value = true; campaignPage.value = page; try { const { data } = await campaignsApi.list({ keyword: keywordFilter.value || undefined, ad_account_id: accountFilter.value || undefined, status: statusFilter.value || undefined, page: campaignPage.value, page_size: campaignPageSize.value }); campaigns.value = data.items; campaignTotal.value = data.total } finally { loading.value = false } }
function handleCampaignPageSizeChange(size: number) { campaignPageSize.value = size; campaignPage.value = 1; loadCampaigns(1) }
function typeLabel(type: string) { return type === 'CAMPAIGN' ? '广告系列' : type === 'ADSET' ? '广告组' : '广告' }
function metaObjectId(value: any) { return value.object?.meta_campaign_id || value.object?.meta_adset_id || value.object?.meta_ad_id || value.campaign?.meta_campaign_id || '-' }
async function showDetail(row: DeliveryRow, type: ObjectType) { try { if (type === 'CAMPAIGN') { const { data } = await campaignsApi.detail(row.id); detail.value = { object_type: type, object: data.campaign, account: data.account, ancestors: {}, children: data.adsets || [], recent_actions: data.recent_actions || [], legacy: data } } else { const { data } = await campaignsApi.objectDetail(type, row.id); detail.value = data } detailVisible.value = true } catch (error: any) { ElMessage.error(error?.response?.data?.detail || '加载详情失败') } }
async function openAdsets(row: MetaCampaign) { selectedCampaign.value = row; selectedCampaignId.value = row.id; selectedAdset.value = null; selectedAdsetId.value = ''; selectedAdsets.value = []; ads.value = []; adsetPage.value = 1; activeTab.value = 'adsets'; await loadAdsets(row.id) }
async function loadAdsets(id: string, page = adsetPage.value) { subLoading.value = true; adsetPage.value = page; try { const selected = campaigns.value.find(item => item.id === id); const ids = selected?.grouped_ids?.length ? selected.grouped_ids : [id]; const responses = await Promise.all(ids.map(campaignId => campaignsApi.adsets(campaignId, adsetStatusFilter.value || undefined, 1, 100))); const merged = [...new Map(responses.flatMap(({ data }) => data.items).map(item => [item.id, item])).values()]; const start = (adsetPage.value - 1) * adsetPageSize.value; adsets.value = merged.slice(start, start + adsetPageSize.value); adsetTotal.value = merged.length } catch (error: any) { adsets.value = []; adsetTotal.value = 0; ElMessage.error(error?.response?.data?.detail || '加载广告组失败') } finally { subLoading.value = false } }
function loadSelectedAdsets(page = adsetPage.value) { if (selectedCampaignId.value) return loadAdsets(selectedCampaignId.value, page) }
function handleAdsetPageSizeChange(size: number) { adsetPageSize.value = size; adsetPage.value = 1; loadSelectedAdsets(1) }
async function selectCampaign(id?: string) { const row = campaigns.value.find(item => item.id === id); selectedCampaign.value = row || null; selectedAdset.value = null; selectedAdsetId.value = ''; selectedAdsets.value = []; ads.value = []; adsetPage.value = 1; if (id) await loadAdsets(id); else { adsets.value = []; adsetTotal.value = 0 } }
async function openAds(row: MetaAdSet) { selectedAdset.value = row; selectedAdsetId.value = row.id; selectedAds.value = []; adPage.value = 1; activeTab.value = 'ads'; await loadAds(row.id) }
async function loadAds(id: string, page = adPage.value) { subLoading.value = true; adPage.value = page; try { const { data } = await campaignsApi.ads(id, adStatusFilter.value || undefined, adPage.value, adPageSize.value); ads.value = data.items; adTotal.value = data.total } catch (error: any) { ads.value = []; adTotal.value = 0; ElMessage.error(error?.response?.data?.detail || '加载广告失败') } finally { subLoading.value = false } }
function loadSelectedAds(page = adPage.value) { if (selectedAdsetId.value) return loadAds(selectedAdsetId.value, page) }
function handleAdPageSizeChange(size: number) { adPageSize.value = size; adPage.value = 1; loadSelectedAds(1) }
async function selectAdset(id?: string) { const row = adsets.value.find(item => item.id === id); selectedAdset.value = row || null; selectedAds.value = []; adPage.value = 1; if (id) await loadAds(id); else { ads.value = []; adTotal.value = 0 } }
function watchTasks(taskIds: string[]) { if (!taskIds.length) return; if (taskTimer) clearTimeout(taskTimer); let round = 0; const poll = async () => { const statuses = await Promise.all(taskIds.map(id => campaignsApi.taskStatus(id).then(({ data }) => data).catch(() => ({ task_id: id, state: 'UNKNOWN', result: undefined })))); const finished = statuses.filter(item => ['SUCCESS', 'FAILURE', 'REVOKED'].includes(item.state)); const failed = statuses.filter(item => ['FAILURE', 'REVOKED'].includes(item.state)); const partial = statuses.filter(item => item.result?.status === 'partial_success'); const errorCount = statuses.reduce((sum, item) => sum + Number(item.result?.error_count || 0), 0); taskNoticeType.value = failed.length ? 'error' : partial.length || errorCount ? 'warning' : finished.length === statuses.length ? 'success' : 'info'; taskNotice.value = finished.length === statuses.length ? (failed.length ? `任务完成：${failed.length} 个失败` : partial.length || errorCount ? `任务完成，但有 ${errorCount || partial.length} 项同步异常` : 'Meta 任务已完成，页面状态已刷新') : `Meta 任务执行中：${finished.length}/${statuses.length}`; if (finished.length === statuses.length || round++ >= 30) { await refresh(); return } taskTimer = setTimeout(poll, 2000) }; poll() }
function watchJobs(jobIds: string[]) { if (!jobIds.length) return; if (jobTimer) clearTimeout(jobTimer); let round = 0; const poll = async () => { const rows = await Promise.all(jobIds.map(id => jobsApi.get(id).then(({ data }) => data).catch(() => null))); const valid = rows.filter(Boolean) as CampaignJob[]; const finished = valid.filter(row => ['SUCCESS', 'PARTIAL_SUCCESS', 'FAILED', 'CANCELLED'].includes(row.status)); const failed = valid.reduce((sum, row) => sum + Number(row.failed_count || 0), 0); if (finished.length === valid.length && valid.length) { batchResult.value = { title: '批量操作已完成', count: valid.reduce((sum, row) => sum + Number(row.total_accounts || 0), 0), message: `成功 ${valid.reduce((sum, row) => sum + Number(row.success_count || 0), 0)}，失败 ${failed}`, failed: failed > 0 }; await refresh(); return } if (round++ >= 30) { batchResult.value = { title: '批量操作仍在执行', count: valid.reduce((sum, row) => sum + Number(row.total_accounts || 0), 0), message: '请在任务列表中查看最新结果' }; return } jobTimer = setTimeout(poll, 2000) }; poll() }
async function sync() { await syncSelected('CAMPAIGN', campaigns.value) }
function objectIds(rows: DeliveryRow[]) { return [...new Set(rows.flatMap(row => (row as MetaCampaign).grouped_ids?.length ? (row as MetaCampaign).grouped_ids! : [row.id]))] }
function rowAccountIds(row: DeliveryRow): string[] { const grouped = (row as MetaCampaign).grouped_accounts; if (Array.isArray(grouped) && grouped.length) return grouped.map(item => item.id).filter(Boolean); const accountId = (row as MetaCampaign).ad_account_id || (row as MetaAdSet).ad_account_id || (row as MetaAd).ad_account_id; return accountId ? [accountId] : [] }
function selectedAccountIds(rows: DeliveryRow[]) { return [...new Set(rows.flatMap(rowAccountIds))] }
async function withOperationLeases<T>(accountIds: string[], operationType: string, callback: (leases: Record<string, string>) => Promise<T>) { if (!accountIds.length) throw new Error('未能解析投放对象所属广告账户'); const held: Array<{ accountId: string; token: string }> = []; const tokens: Record<string, string> = {}; try { for (const accountId of accountIds) { const { data } = await accountApi.acquireOperationLease(accountId, operationType, 120); const token = data?.lease?.lease_token; if (!token) throw new Error('未能获取广告账户操作租约'); held.push({ accountId, token }); tokens[accountId] = token } return await callback(tokens) } finally { await Promise.allSettled(held.map(({ accountId, token }) => accountApi.releaseOperationLease(accountId, token))) } }
async function syncSelected(type: ObjectType, rows: DeliveryRow[]) { if (!canCampaignAction('SYNC')) { ElMessage.warning('没有 Meta 同步权限'); return } if (!rows.length) { ElMessage.warning('请先选择投放对象'); return } try { const ids = objectIds(rows); const accountIds = selectedAccountIds(rows); await withOperationLeases(accountIds, 'CAMPAIGN_SYNC', async operationLeases => { const { data } = await campaignsApi.sync(ids, type, operationLeases); ElMessage.success(`已提交 ${ids.length} 个${typeLabel(type)}的 Meta 状态同步`); taskNotice.value = 'Meta 实时状态同步已提交'; batchResult.value = { title: 'Meta 状态同步', count: ids.length, message: `已按 ${data.account_ids?.length || 0} 个广告账户执行同步` }; activeTab.value = 'jobs'; await loadJobs(); watchTasks(data.task_ids || []) }) } catch (error: any) { ElMessage.error(error?.response?.data?.detail || error?.message || '提交同步任务失败') } }
async function batchAction(action: string, type: ObjectType, rows: DeliveryRow[]) { if (action === 'DELETE') { await openMetaDeletion(type, rows); return } if (!canCampaignAction(action)) { ElMessage.warning(`没有${actionLabel(action)}权限`); return } if (!rows.length) { ElMessage.warning('请先选择投放对象'); return } try { const ids = objectIds(rows); await ElMessageBox.confirm(`确认对选中的 ${rows.length} 个逻辑${typeLabel(type)}（共 ${ids.length} 个账户实例）执行「${actionLabel(action)}」？${['ARCHIVE', 'RESTORE'].includes(action) ? '本地归档会先暂停 Meta 投放，取消归档后仍保持暂停。' : ''}`, '确认批量操作', { type: 'warning' }); const accountIds = selectedAccountIds(rows); await withOperationLeases(accountIds, 'CAMPAIGN_ACTION', async operationLeases => { const { data } = await campaignsApi.action({ action, ids, object_type: type, operation_leases: operationLeases, idempotency_key: actionKey(action, ids.join(',')) }); batchResult.value = { title: `批量${actionLabel(action)}已提交`, count: ids.length, message: data.task_ids?.length ? '正在等待 Meta 返回结果' : '正在按广告账户执行任务' }; taskNotice.value = `批量${actionLabel(action)}任务已提交`; activeTab.value = 'jobs'; await loadJobs(); if (data.action_ids?.length) watchActions(data.action_ids); else if (data.task_ids?.length) watchTasks(data.task_ids); if (data.job_ids?.length) watchJobs(data.job_ids) }) } catch (error: any) { if (error?.response?.data?.detail) ElMessage.error(error.response.data.detail); else if (error?.message) ElMessage.error(error.message) } }
function actionKey(action: string, id: string) { return `${action}:${id}:${Date.now()}:${Math.random().toString(16).slice(2)}` }
async function changeStatus(row: DeliveryRow, type: ObjectType) { await batchAction(row.status === 'ACTIVE' ? 'PAUSE' : 'ENABLE', type, [row]) }
async function archive(row: DeliveryRow, type: ObjectType) { await batchAction('ARCHIVE', type, [row]) }
async function removePublished(row: DeliveryRow, type: ObjectType) { await batchAction('DELETE', type, [row]) }
async function restore(row: DeliveryRow, type: ObjectType) { await batchAction('RESTORE', type, [row]) }
async function retryAction(row: DeliveryAction) {
  if (!canCampaignAction(row.action)) { ElMessage.warning('没有操作权限'); return }
  try {
    await ElMessageBox.confirm(row.status === 'UNKNOWN' ? '只查询删除回执与 Meta 状态，不再次发送删除请求。确认核对？' : '只重试这条失败操作，原记录保留。确认提交？', '确认操作', { type: 'warning' })
    await withOperationLeases([row.account_id], 'CAMPAIGN_RETRY', async leases => {
      const { data } = await campaignsApi.retryDeliveryAction(row.id, leases[row.account_id])
      taskNotice.value = row.status === 'UNKNOWN' ? '删除结果核对已提交' : '失败项重试已提交'
      await loadJobs(); watchActions([data.action_id])
    })
  } catch (error: any) { if (error?.response?.data?.detail) ElMessage.error(error.response.data.detail) }
}
async function showActionDetail(row: DeliveryAction) { try { const { data } = await campaignsApi.objectDetail(row.object_type, row.object_id); detail.value = data; detailVisible.value = true } catch { ElMessage.error('加载操作对象详情失败') } }
async function loadJobs() { jobLoading.value = true; try { const [{ data: jobData }, { data: taskData }, { data: actionData }] = await Promise.all([jobsApi.list({ limit: 50 }), campaignsApi.taskRecords(50), campaignsApi.deliveryActions(50)]); jobs.value = jobData; metaTasks.value = taskData; deliveryActions.value = actionData } finally { jobLoading.value = false } }
async function openJob(row: CampaignJob) { try { const { data } = await jobsApi.get(row.id); jobDetail.value = data; jobDetailVisible.value = true } catch { ElMessage.error('加载批量任务结果失败') } }
async function refresh() { await loadCampaigns(); await loadJobs() }
async function onTabChange(tab: string | number) { if (tab === 'jobs') await loadJobs(); else if (tab === 'adsets') { if (!selectedCampaignId.value && campaigns.value.length) await selectCampaign(campaigns.value[0].id); else if (!selectedCampaignId.value) { adsets.value = []; adsetTotal.value = 0 } } else if (tab === 'ads') { if (!selectedAdsetId.value && adsets.value.length) await selectAdset(adsets.value[0].id); else if (!selectedAdsetId.value) { ads.value = []; adTotal.value = 0 } } }
function actionLabel(action: string) { return ({ DELETE: '删除 Meta 广告', ARCHIVE: '本地归档', RESTORE: '取消归档', PAUSE: '暂停', ENABLE: '启用' } as Record<string, string>)[action] || action }
async function copyDeletedCampaign(row: MetaCampaign) {
  try {
    const { data: source } = await campaignsApi.detail(row.id)
    if (!source.template?.id) { ElMessage.warning('没有原投放模板的查看权限，请使用有权限的模板新建投放'); return }
    const { data: template } = await templatesApi.clone(source.template.id)
    await router.push({ path: '/dashboard/batch-publish', query: { template_id: template.id, account_ids: selectedAccountIds([row]).join(',') } })
  } catch (error: any) { ElMessage.error(error?.response?.data?.detail || '复制新建失败') }
}
function actionStateLabel(row: DeliveryAction) {
  return ({ REQUESTED: '排队中', RUNNING: row.action === 'DELETE' ? '删除中' : '执行中', UNKNOWN: '删除结果待确认', FAILED: '失败', SUCCESS: row.action === 'DELETE' ? 'Meta 删除成功' : '成功' } as Record<string, string>)[row.status] || row.status
}
function objectOperationLabel(row: DeliveryRow) {
  const ids = objectIds([row])
  const latest = ids.map(id => deliveryActions.value.find(action => action.object_id === id)).filter(Boolean) as DeliveryAction[]
  const pending = latest.filter(action => ['REQUESTED', 'RUNNING', 'UNKNOWN', 'FAILED'].includes(action.status))
  if (!pending.length) return '-'
  return pending.length > 1 ? `${pending.length} 项待处理` : actionStateLabel(pending[0])
}
function watchActions(ids: string[]) {
  if (!ids.length) { taskNoticeType.value = 'warning'; taskNotice.value = '未收到对象操作记录，请确认国内服务已更新'; return }
  if (actionTimer) clearTimeout(actionTimer)
  let round = 0
  const poll = async () => {
    const records = await Promise.all(ids.map(id => campaignsApi.deliveryAction(id).then(({ data }) => data).catch(() => null)))
    const rows = records.filter(Boolean) as DeliveryAction[]
    const success = rows.filter(row => row.status === 'SUCCESS').length
    const failed = rows.filter(row => row.status === 'FAILED').length
    const unknown = rows.filter(row => row.status === 'UNKNOWN').length
    const finished = success + failed + unknown
    taskNoticeType.value = failed || unknown ? 'warning' : finished === ids.length ? 'success' : 'info'
    taskNotice.value = `对象操作：成功 ${success}，失败 ${failed}，待确认 ${unknown}，执行中 ${ids.length - finished}`
    deliveryActions.value = [...rows, ...deliveryActions.value.filter(row => !ids.includes(row.id))]
    if (finished === ids.length || round++ >= 30) {
      batchResult.value = { title: finished === ids.length ? '操作结果已返回' : '操作仍在执行', count: ids.length, message: taskNotice.value, failed: failed + unknown > 0 }
      await refresh(); await loadSelectedAdsets(); await loadSelectedAds()
      return
    }
    actionTimer = setTimeout(poll, 2000)
  }
  void poll()
}
async function openMetaDeletion(type: ObjectType, rows: DeliveryRow[]) {
  if (!canCampaignAction('DELETE')) { ElMessage.warning('没有 Meta 删除权限'); return }
  if (!rows.length) { ElMessage.warning('请先选择投放对象'); return }
  try {
    const ids = objectIds(rows)
    const details = await Promise.all(ids.map(id => campaignsApi.objectDetail(type, id).then(({ data }) => data)))
    deleteType.value = type
    deleteTargets.value = details.filter(item => item.object.deletion_state !== 'REMOTE_DELETED').map(item => ({
      id: item.object.id, name: item.object.name, accountId: item.account?.id || '',
      accountName: item.account?.account_name || item.account?.account_id || '-', metaId: metaObjectId(item),
      state: item.object.deletion_state === 'LOCAL_REMOVED' ? '历史本地移除' : item.object.status,
      scope: type === 'CAMPAIGN' ? `${item.children.length} 个广告组，${item.children.reduce((count, child) => count + (child.ads?.length || 0), 0)} 个广告` : type === 'ADSET' ? `${item.children.length} 个广告` : '仅此广告',
    }))
    if (!deleteTargets.value.length) { ElMessage.info('所选对象已在 Meta 删除'); return }
    deleteSelection.value = []
    deleteVisible.value = true
    await nextTick()
    deleteTargets.value.forEach(row => deleteTable.value?.toggleRowSelection(row, true))
  } catch (error: any) { ElMessage.error(error?.response?.data?.detail || '加载删除范围失败') }
}
async function submitMetaDeletion() {
  if (!deleteSelection.value.length || deleteSubmitting.value) return
  const selected = [...deleteSelection.value]
  deleteSubmitting.value = true
  try {
    const ids = selected.map(row => row.id)
    await withOperationLeases([...new Set(selected.map(row => row.accountId))], 'CAMPAIGN_ACTION', async leases => {
      const { data } = await campaignsApi.action({ action: 'DELETE', object_type: deleteType.value, ids, operation_leases: leases, idempotency_key: actionKey('DELETE', ids.join(',')) })
      deleteVisible.value = false
      taskNoticeType.value = 'info'; taskNotice.value = '删除任务已提交，等待 Meta 确认'
      batchResult.value = { title: 'Meta 删除任务已提交', count: ids.length, message: '正在等待实际删除结果' }
      activeTab.value = 'jobs'
      await loadJobs(); watchActions(data.action_ids || [])
    })
  } catch (error: any) { ElMessage.error(error?.response?.data?.detail || error?.message || '删除任务提交失败') }
  finally { deleteSubmitting.value = false }
}
onMounted(refresh)
onBeforeUnmount(() => { if (refreshTimer) clearTimeout(refreshTimer); if (taskTimer) clearTimeout(taskTimer); if (jobTimer) clearTimeout(jobTimer); if (actionTimer) clearTimeout(actionTimer) })
</script>
<style scoped>
.campaigns-page{padding:4px}.page-head{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:18px}.eyebrow{color:#829ab1;font-size:12px}.page-head h2{margin:6px 0;color:#102a43}.page-head p{margin:0;color:#627d98;font-size:13px}.filters,.batch-toolbar,.selector-row{display:flex;align-items:center;gap:8px}.filters,.batch-toolbar{margin-bottom:12px}.filters .el-input{width:220px}.filters .el-select,.selector-row .el-select{width:160px}.selector-row .el-select:first-child{width:320px}.batch-toolbar{flex-wrap:wrap;color:#52606d;font-size:13px}.sub-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;color:#52606d}.pagination-bar{display:flex;justify-content:flex-end;margin-top:16px}.detail-section{margin-top:18px}.detail-section h4{margin:0 0 8px;color:#334e68}.detail-json{max-height:240px;overflow:auto;background:#f5f7fa;padding:12px;border-radius:4px;font-size:12px;white-space:pre-wrap;word-break:break-all}.result-summary{display:flex;align-items:center;gap:8px}.success-text{color:#67c23a}.failed-text{color:#f56c6c}
